<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class qqworld_collector_parse_pixiv_net_archive_request_method extends lib { var $post_content = array(); public function __construct() { add_filter( 'qqworld-collector-parse-pixiv-net-archive-request-method', array($this, 'filter'), 10, 6 ); } public function filter($item, $source_link, $html, $type, $item_args, $download_args) { $preg = preg_match('/users\/(\d*?)\//i', $source_link, $match); if ($preg) { $id = $match[1]; $url = 'https://www.pixiv.net/ajax/user/'.$id.'/profile/all?lang=zh'; $response = wp_remote_get($url, $download_args); $body = wp_remote_retrieve_body($response); if ($body) { $preg = preg_match('/illusts":\{.*?\}/', $body, $match); if ($preg) { $preg = preg_match_all('/"(\d*?)":null/', $match[0], $matches); if ($preg) { $url = 'https://www.pixiv.net/ajax/user/810305/profile/illusts?ids%5B%5D='.implode('&ids%5B%5D=', $matches[1]).'&work_category=illustManga&is_first_page=1&lang=zh'; $response = wp_remote_get($url, $download_args); $body = wp_remote_retrieve_body($response); if ($body) $item = $body; } } } } return $item; } } new qqworld_collector_parse_pixiv_net_archive_request_method; ?>